programming-021.code:
○整數型: s(整數型: n)
  if (n ≦ 0)
    return 0
  endif
  return n + s(n − 2)

programming-024.code:
○整數型: c(整數型: n, 整數型: k)
  if (k = 0 or k = n)
    return 1
  endif
  return c(n − 1, k − 1) + c(n − 1, k)

